CREATE OR REPLACE VIEW {{DATABASE}}.GOLD.ORDER_REVENUE AS SELECT O.ORDER_ID,O.ORDER_DATE,O.STATUS,O.CUSTOMER_ID,C.FIRST_NAME,C.LAST_NAME,C.COUNTRY,SUM(S.TOTAL_AMOUNT) ORDER_REVENUE FROM {{DATABASE}}.SILVER.ORDERS O JOIN {{DATABASE}}.SILVER.CUSTOMERS C ON O.CUSTOMER_ID=C.CUSTOMER_ID JOIN {{DATABASE}}.SILVER.SALES S ON O.ORDER_ID=S.ORDER_ID GROUP BY O.ORDER_ID,O.ORDER_DATE,O.STATUS,O.CUSTOMER_ID,C.FIRST_NAME,C.LAST_NAME,C.COUNTRY;
CREATE OR REPLACE VIEW {{DATABASE}}.GOLD.PRODUCT_REVENUE AS SELECT P.PRODUCT_ID,P.PRODUCT_NAME,P.CATEGORY,P.ACTIVE,SUM(S.QUANTITY) UNITS_SOLD,SUM(S.TOTAL_AMOUNT) REVENUE FROM {{DATABASE}}.SILVER.SALES S JOIN {{DATABASE}}.SILVER.PRODUCTS P ON S.PRODUCT_ID=P.PRODUCT_ID GROUP BY P.PRODUCT_ID,P.PRODUCT_NAME,P.CATEGORY,P.ACTIVE;
CREATE OR REPLACE VIEW {{DATABASE}}.GOLD.CUSTOMER_REVENUE AS SELECT C.CUSTOMER_ID,C.FIRST_NAME,C.LAST_NAME,C.EMAIL,C.COUNTRY,COUNT(DISTINCT O.ORDER_ID) ORDER_COUNT,SUM(S.TOTAL_AMOUNT) TOTAL_REVENUE FROM {{DATABASE}}.SILVER.CUSTOMERS C JOIN {{DATABASE}}.SILVER.ORDERS O ON C.CUSTOMER_ID=O.CUSTOMER_ID JOIN {{DATABASE}}.SILVER.SALES S ON O.ORDER_ID=S.ORDER_ID GROUP BY C.CUSTOMER_ID,C.FIRST_NAME,C.LAST_NAME,C.EMAIL,C.COUNTRY;
CREATE OR REPLACE VIEW {{DATABASE}}.GOLD.MONTHLY_REVENUE AS SELECT DATE_TRUNC('MONTH',O.ORDER_DATE) REVENUE_MONTH,COUNT(DISTINCT O.ORDER_ID) ORDER_COUNT,SUM(S.TOTAL_AMOUNT) TOTAL_REVENUE FROM {{DATABASE}}.SILVER.ORDERS O JOIN {{DATABASE}}.SILVER.SALES S ON O.ORDER_ID=S.ORDER_ID GROUP BY DATE_TRUNC('MONTH',O.ORDER_DATE);
